namespace ghidra.app.plugin.core.decompile.actions;

using ghidra.app.decompiler;
using ghidra.app.plugin.core.decompile;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.pcode;
using ghidra.program.model.pcode.HighFunctionDBUtil;
using ghidra.program.model.symbol;
using ghidra.util.exception;
using ghidra.util.exception;

public class RenameVariableTask : RenameTask {

	private HighSymbol highSymbol;
	private Varnode exactSpot;
	private HighFunction hfunction;
	private Function function;
	private bool commitRequired; // Set to true if all parameters are committed before renaming
	private SourceType srctype;		// Desired source type for the variable being renamed
	private SourceType signatureSrcType;	// Signature source type of the function (which will be preserved)

	public RenameVariableTask(PluginTool tool, Program program, DecompilerProvider provider,
			ClangToken token, HighSymbol sym, SourceType st) : base(tool, program, provider, token, sym.getName())
    {
		highSymbol = sym;
		exactSpot = token.getVarnode();
		hfunction = sym.getHighFunction();
		function = hfunction.getFunction();
		srctype = st;
		signatureSrcType = function.getSignatureSource();
	}

	/* @Override */
	public void commit()
    {
		if (commitRequired) {
			HighFunctionDBUtil.commitParamsToDatabase(hfunction, false,
				ReturnCommitOption.NO_COMMIT, signatureSrcType);
		}
		HighFunctionDBUtil.updateDBVariable(highSymbol, newName, null, srctype);
	}

	/* @Override */
	public bool isValid(string newNm) {
		newName = newNm;
		if (isSymbolInFunction(function, newName)) {
			errorMsg = "Duplicate name";
			return false;
		}
		commitRequired = AbstractDecompilerAction.checkFullCommit(highSymbol, hfunction);
		if (commitRequired) {
			exactSpot = null; // Don't try to split out if we need to commit
		}

		if (exactSpot != null && !highSymbol.isNameLocked()) { // The user pointed at a particular usage, not just the vardecl
			try {
				HighVariable var = hfunction.splitOutMergeGroup(exactSpot.getHigh(), exactSpot);
				highSymbol = var.getSymbol();
			}
			catch (PcodeException e) {
				errorMsg = "Rename Failed: " + e.getMessage();
				return false;
			}
		}
		if (highSymbol == null) {
			errorMsg = "Rename Failed: No symbol";
			return false;
		}
		return true;
	}

	/* @Override */
	public string getTransactionName() {
		return "Rename Local Variable";
	}
}
